-- D-04 Change Management, DRAFT:
--   FSQM-007 Change Management Program
--   FRM-015  Change Assessment Record
--
-- Four Minor findings: 2.1.1.7, 2.2.1.2, 2.3.1.4, 2.3.1.5. FSQM-007 is reserved in the remediation
-- workbook; FRM-015 is the next free FRM-0xx number.
--
-- Most of the rule already exists and is not rewritten: FSQM-017 Part 4 (assess a change BEFORE it takes
-- effect, with its triggers - and it says this deliverable defines the record), FSQM-004 (a named cover
-- for every key position), FSQM-005 / FRM-001 (the yearly review of the system). FSQM-007 joins them and
-- adds the four things that were missing: the review of the manufacturing process, not only the recipe
-- (2.3.1.4); the process flow rule (2.3.1.5); the handover when people change (2.1.1.7); and the record.
-- SOP-2.3.1 (active) points at a "Management of Change Procedure" that never existed - this is it.
--
-- One form, not several: a label (FRM-601), a supplier (FRM-202), a material (FRM-207) and a corrective
-- action (FRM-007) keep their own records; FRM-015 is for every other change.
-- The active documents it will amend - FSQM-017 Part 4 and SOP-2.3.1 - are left untouched here and are
-- revised in the issue migration. No verification schedule row: a change is not a dated activity.

begin;

do $guard$
begin
  if exists (select 1 from public.sop_documents where sop_number in ('FSQM-007', 'FRM-015')) then
    raise exception 'a D-04 document number is already in use.';
  end if;
  if (select count(distinct sop_number) from public.sop_documents
       where sop_number in ('FSQM-004', 'FSQM-005', 'FSQM-009', 'FSQM-016', 'FSQM-017', 'FSQM-025', 'FSQM-027', 'FSQM-029', 'FSQM-030', 'SOP-2.2.3', 'SOP-2.3.1', 'SOP-2.9', 'FRM-001', 'FRM-004', 'FRM-005', 'FRM-007', 'FRM-009', 'FRM-202', 'FRM-207', 'FRM-502', 'FRM-601', 'FRM-704', 'FRM-952') and status in ('active', 'draft')) <> 23 then
    raise exception 'a document D-04 names is missing: %', (
      select string_agg(n, ', ') from unnest(array['FSQM-004', 'FSQM-005', 'FSQM-009', 'FSQM-016', 'FSQM-017', 'FSQM-025', 'FSQM-027', 'FSQM-029', 'FSQM-030', 'SOP-2.2.3', 'SOP-2.3.1', 'SOP-2.9', 'FRM-001', 'FRM-004', 'FRM-005', 'FRM-007', 'FRM-009', 'FRM-202', 'FRM-207', 'FRM-502', 'FRM-601', 'FRM-704', 'FRM-952']) n
       where not exists (select 1 from public.sop_documents d where d.sop_number = n and d.status in ('active', 'draft')));
  end if;
end $guard$;

insert into public.sop_documents
  (sop_number, title, type, category, status, revision, sqf_reference, sqf_required, content)
values
  ('FSQM-007', 'Change Management Program', 'fsqm', 'Food Safety Quality Manual', 'draft', 'New',
   '2.1.1.7, 2.2.1.2, 2.3.1.4, 2.3.1.5', true, $q${"purpose": "This program states how Adventure Bakery makes a change - to a product, a process, equipment, people or the organization - without losing control of food safety: every change is assessed and approved before it takes effect, the reason is recorded, and the people affected are told.", "scope": "Every change that could affect the safety of the product or the running of the SQF System, on the whole site.", "definitions": "Change: anything new or different that could affect product safety or the SQF System.\nAssessment: working out, before the change, what it touches and what is needed to keep the product safe.\nValidate: show, by a trial or a measurement, that the changed process does what it must.\nJustify: show, from a specification or a regulatory standard, that the change is safe without a trial.\nKey position: a position named in FSQM-004 as holding a food safety duty.", "responsibility": "Senior Site Management - approves every change before it takes effect, keeps the SQF System running through changes of people and organization, and reviews the year's changes in the annual management review.\nSQF Practitioner - assesses each change, revises the food safety plan and the documents it touches, sees that staff are told and trained, and checks the change afterwards. The substitute SQF Practitioner covers when the SQF Practitioner is away.\nAll staff - make no change to a recipe, a process, a limit, equipment or a cleaning method on their own, and tell the SQF Practitioner when one is needed.", "procedure": ["What counts as a change", "• A change is anything new or different that could affect the safety of the product or the way the SQF System runs:", "◦ a new product, or a change to a product's recipe;", "◦ a new or altered process step, or a change to a time, a temperature or another limit;", "◦ new, moved or modified equipment;", "◦ a new ingredient, a different brand of an ingredient, or a new supplier;", "◦ new packaging or a changed label;", "◦ a change to the layout of the site or to where things are kept;", "◦ a change to a cleaning method or a cleaning chemical;", "◦ a person joining, leaving or changing position, or a change in who owns or manages the business.", "• Not a change: replacing a part or a material with the same one - the same maker and the same model or product.", "The rule", "• No change takes effect until it has been assessed and approved. The SQF Practitioner assesses it. Senior Site Management approves it.", "• The assessment comes first. A control that is checked after the change has already failed to control it (FSQM-017 Part 4).", "• The reason for the change is written down, and the change is validated or justified before it is made: by a trial, a measurement, the maker's specification, or a regulatory standard (SQF 2.2.1.2).", "Which record", "• Where a record already governs the change, that record is used and nothing is written twice:", "◦ a label - FRM-601;", "◦ a new supplier - FRM-202;", "◦ a new material, or a different brand of one already used - FRM-207, with its allergen statement checked first;", "◦ a change that comes out of a corrective action - the FRM-007 that raised it.", "• Every other change is assessed on FRM-015: a new product, a change to a recipe, a process step or a limit, new or modified equipment, a change of layout or of a cleaning method, and a change of people.", "Assessing a change to a product, a process or equipment", "• The assessment reviews the manufacturing process, not only the recipe: every step the change touches, the equipment, the times and temperatures, the cleaning, and who does the work (SQF 2.3.1.4).", "• A trial run does not replace it. The trial shows the product can be made; the review shows it can be made safely. The first production run is recorded on FRM-502.", "• For each line below, FRM-015 records whether the change touches it and what is needed:", "◦ The food safety plan (FSQM-016): does a hazard appear, change, or lose its control? If so, the food safety team revises the plan and validates it before the change.", "◦ The process flow diagram: is it still true?", "◦ Allergens and the changeover rule (FSQM-027), and the label (FRM-601).", "◦ The product specification (FRM-704) and the material specifications (FRM-207).", "◦ Cleaning, the equipment register (FRM-004), maintenance (FSQM-029) and calibration (FSQM-030).", "◦ Storage, the lot record and traceability.", "◦ Training: who has to be trained before the change.", "◦ Documents to revise, and the verification schedule (FSQM-017 Part 6).", "• Process flows, new and existing, are laid out so that the product is made to its approved recipe and so that nothing contaminates it: unbaked does not cross baked, a nut product does not cross a product without that nut, and waste, people and materials do not carry dirt to open product. A new or changed flow is walked on the floor and confirmed before it is used (SQF 2.3.1.5).", "Changes to people and to the organization", "• Senior Site Management makes sure the SQF System keeps running when people or the organization change (SQF 2.1.1.7).", "• Every key position has a named cover (FSQM-004). When the holder is away, the cover acts.", "• When a person leaves, joins or changes position, FRM-015 records:", "◦ each food safety duty the person held, and who holds it now;", "◦ the open work handed over - open corrective actions, checks that are due, and records waiting for a signature;", "◦ the training the new holder completed before working alone (SOP-2.9, FRM-952);", "◦ Team Portal access closed for the person leaving, the same day, and opened for the new holder; keys returned (FSQM-025).", "• A change of SQF Practitioner or substitute is also recorded on FRM-005.", "• A change of owner or of management is assessed the same way, and the certification body is told where its rules require it.", "Telling people", "• Before a change takes effect, everyone it affects is told what is changing and from when.", "• Where a procedure or a record changes, the document is revised and issued under SOP-2.2.3, and staff are trained on it before they use it (SOP-2.9) (SQF 2.2.1.2).", "After the change", "• The SQF Practitioner checks the first run, or the first weeks, after the change and records on FRM-015 that it works as assessed. A problem is raised as a corrective action on FRM-007 under FSQM-009.", "The yearly review of the system", "• The whole SQF System is reviewed at least once a year in the annual management review (FSQM-005, FRM-001). The year's FRM-015 records go to that review, which asks whether the food safety plan, the programs and the documents are still right after the changes made. Changes are also reported in the monthly update on FRM-009 (SQF 2.2.1.2).", "Records", "• FRM-015 records, and the FRM-601, FRM-202, FRM-207 and FRM-007 records that stand in for it, are kept as SOP-2.2.3 requires."], "form_references": "FRM-015 - Change Assessment Record\nFRM-601 - Label Review & Approval Form\nFRM-202 - Supplier Approval & Evaluation Record\nFRM-207 - Material Specification Register\nFRM-007 - Corrective & Preventive Action (CAPA) Report\nFRM-502 - First Production Run Report & QC Results\nFRM-704 - Finished Product Specification\nFRM-004 - Equipment Register\nFRM-005 - SQF Practitioner Designation Record\nFRM-952 - Training Competency Verification Record\nFRM-001 - Management Review Record\nFRM-009 - Monthly SQF Update Record", "records": "• FRM-015 - one per change that has no record of its own\n• FRM-601, FRM-202, FRM-207 and FRM-007 - where they govern the change\n• FRM-001 - the yearly review of the system", "governing_reference": "SQF Food Safety Code: Food Manufacturing, Edition 9 - 2.1.1.7 (changes to people and organization), 2.2.1.2 (changes to the SQF System), 2.3.1.4 and 2.3.1.5 (changes to formulations, processes and process flows).\n\nFSQM-017 Validation and Verification Program - Part 4, the rule that a change is assessed before it takes effect.\nFSQM-016 Food Safety Plan (HACCP).\nFSQM-005 Management Review Program.\nFSQM-004 Organizational Structure and Responsibilities - the positions named here and their covers.\nFSQM-009 CAPA Program; FSQM-025 Food Defense Plan; FSQM-027 Allergen Management Program; FSQM-029 Preventive Maintenance Program; FSQM-030 Calibration Program.\nSOP-2.3.1 New Product and Specification Process; SOP-2.2.3 Document and Record Control Program; SOP-2.9 Training & Recordkeeping.", "revision_history": "New - 2026-10-05 - DRAFT under D-04, for the Minor findings against 2.1.1.7, 2.2.1.2, 2.3.1.4 and 2.3.1.5. The site had no change management procedure; SOP-2.3.1 pointed at a \"Management of Change Procedure\" that did not exist.\n\nWHAT WAS ALREADY THERE: FSQM-017 Part 4 already states the rule - assess before the change - and its triggers, and says this deliverable would define the record. That record is FRM-015. FSQM-004 already names a cover for every key position. FSQM-005 already holds the yearly review of the system on FRM-001. This program joins them and adds what was missing: the process review (2.3.1.4), the process flow rule (2.3.1.5), the handover when people change (2.1.1.7), and the record.\n\nONE FORM, NOT SEVERAL: a label, a supplier, a material and a corrective action each have their own record already, and FRM-015 is not filled in beside them.\n\nNo verification schedule row: a change is assessed when it happens, not on a date. The yearly look is the management review.\n\nAT ISSUE: revise FSQM-017 Part 4 to name FSQM-007 and FRM-015 in place of its interim rule; revise SOP-2.3.1 so that \"the Management of Change Procedure\" reads FSQM-007 and the process review is a step of a new product.\n\nTO CONFIRM BEFORE ISSUE: (1) how staff are told of a change today - a talk before the shift, a message, or the Team Portal; (2) that no other company or site is tied to this one in a way that a change there would reach this site; (3) the first real change recorded on FRM-015."}$q$::jsonb),
  ('FRM-015', 'Change Assessment Record', 'form', 'Module 2', 'draft', 'New',
   '2.1.1.7, 2.2.1.2, 2.3.1.4', true, jsonb_build_object('form_schema', $q${"schemaVersion": 1, "settings": {"attachmentsEnabled": true, "allowMultipleDrafts": true, "requireVerification": true, "instanceTitleTemplate": "{change_type} - {raised_on}"}, "sections": [{"id": "change", "title": "1. The change", "fields": [{"id": "how_this_works", "type": "info", "label": "How to use this", "text": "One record for each change that has no record of its own (FSQM-007). Do not use it for a label (FRM-601), a new supplier (FRM-202), a new material or brand (FRM-207), or a change that comes out of a corrective action (FRM-007). Fill in sections 1 to 3 BEFORE the change is made. Section 4 is filled in afterwards."}, {"id": "change_type", "type": "select", "label": "Kind of change", "width": "third", "required": true, "showInList": true, "options": ["New product", "Recipe", "Process step or limit", "Equipment", "Site layout or storage", "Cleaning method or chemical", "People or organization", "Other"]}, {"id": "raised_on", "type": "date", "label": "Date raised", "width": "third", "required": true, "showInList": true}, {"id": "planned_for", "type": "date", "label": "Planned to take effect", "width": "third"}, {"id": "description", "type": "textarea", "label": "What is changing", "required": true, "showInList": true, "help": "From what, to what, and on which product, step or machine"}, {"id": "reason", "type": "textarea", "label": "Reason for the change", "required": true}]}, {"id": "assessment", "title": "2. Assessment - product, process or equipment", "description": "For a change of people only, mark every line \"Not touched\" and go to section 3.", "fields": [{"id": "touches", "type": "grid", "label": "What the change touches", "required": true, "rowDialog": true, "columns": [{"id": "touched", "label": "Touched?", "type": "select", "options": ["Touched", "Not touched"], "required": true, "width": 1}, {"id": "needed", "label": "What is needed before the change", "type": "text", "width": 3, "scanFact": "none"}], "rows": {"mode": "fixed", "labels": ["Food safety plan - hazards, CCPs and limits (FSQM-016)", "Process flow diagram", "Allergens and the changeover rule (FSQM-027)", "Label (FRM-601)", "Product and material specifications (FRM-704, FRM-207)", "Cleaning, equipment register, maintenance, calibration", "Storage, lot record and traceability", "Training needed before the change", "Documents and the verification schedule to revise"], "labelHeader": "Reviewed"}}, {"id": "process_review", "type": "textarea", "label": "Review of the manufacturing process", "help": "Each step the change touches, the equipment, times and temperatures, cleaning, and who does the work. A trial run does not replace this."}, {"id": "validation", "type": "textarea", "label": "How the change was shown to be safe", "required": true, "help": "A trial, a measurement, the maker's specification, or a regulatory standard. Say which, and attach it."}]}, {"id": "people", "title": "3. Change of people or organization only", "description": "Leave blank for any other change.", "fields": [{"id": "duties", "type": "grid", "label": "Duties handed over", "columns": [{"id": "duty", "label": "Food safety duty", "type": "text", "width": 2, "scanFact": "none"}, {"id": "from", "label": "Held by", "type": "text", "width": 1.2, "scanFact": "none"}, {"id": "to", "label": "Now held by", "type": "text", "width": 1.2, "scanFact": "none"}, {"id": "trained", "label": "Trained on", "type": "date", "width": 1}], "rows": {"mode": "dynamic", "min": 1, "addLabel": "Add duty"}}, {"id": "open_work", "type": "textarea", "label": "Open work handed over", "help": "Open corrective actions, checks that are due, records waiting for a signature. Write None if there is none."}, {"id": "access", "type": "textarea", "label": "Team Portal access and keys", "help": "Access closed for the person leaving and the date; access opened for the new holder; keys returned"}]}, {"id": "decision", "title": "4. Decision, and after the change", "fields": [{"id": "decision", "type": "select", "label": "Decision", "width": "third", "required": true, "showInList": true, "options": ["Approved", "Approved with conditions", "Not approved"]}, {"id": "conditions", "type": "textarea", "label": "Conditions, if any"}, {"id": "told", "type": "textarea", "label": "Who was told, how and when", "help": "Everyone the change affects, before it takes effect"}, {"id": "effective_on", "type": "date", "label": "Took effect on", "width": "third"}, {"id": "follow_up", "type": "textarea", "label": "Check after the change", "help": "The first run or the first weeks: does it work as assessed?"}, {"id": "capa_no", "type": "text", "label": "CAPA Report no. (FRM-007)", "width": "third"}]}, {"id": "sign", "title": "5. Sign-off", "fields": [{"id": "assessed_by", "type": "signature", "label": "Assessed by", "role": "filler", "required": true, "statement": "I assessed this change before it was made."}, {"id": "approved_by", "type": "signature", "label": "Approved by Senior Site Management", "role": "verifier", "required": true, "statement": "I approve this change on the assessment above."}]}]}$q$::jsonb));

do $verify$
declare p jsonb;
begin
  select content->'procedure' into p from public.sop_documents where sop_number = 'FSQM-007';
  if jsonb_array_length(p) <> 54 then raise exception 'FSQM-007 procedure is % lines, expected 54.', jsonb_array_length(p); end if;
  if (select count(*) from unnest(array['2.1.1.7)', '2.2.1.2)', '2.3.1.4)', '2.3.1.5)']) c where p::text like '%' || c || '%') <> 4 then
    raise exception 'FSQM-007 does not cite every clause it closes.';
  end if;
  if exists (select 1 from public.sop_documents where sop_number in ('FSQM-007', 'FRM-015')
              and content::text ~* 'Diana|Gabriela|Christina|GJM|Mercer|Pillsbury|Amazon|Sysco|Bahamas') then
    raise exception 'a D-04 document names a person, a supplier or a customer; controlled documents name positions.';
  end if;
  if (select count(*) from public.sop_documents d, jsonb_array_elements(d.content->'form_schema'->'sections') s,
                           jsonb_array_elements(s->'fields') f where d.sop_number = 'FRM-015') <> 20 then
    raise exception 'FRM-015 field count is wrong.';
  end if;
  if (select string_agg(status || ' ' || revision, ', ' order by sop_number) from public.sop_documents
       where sop_number in ('FSQM-017', 'SOP-2.3.1') and status = 'active') is distinct from 'active v11, active v1' then
    raise exception 'FSQM-017 or SOP-2.3.1 is not at the revision this draft was written against.';
  end if;
end $verify$;

commit;
